-- A sample of the Guelph Transit GTFS feed (service 2026-01-04 to 2026-05-02),
-- routes 1, 2, 99, trips starting 07:00-08:59, made by data/make_sample.py.

CREATE TABLE agency (agency_id TEXT, agency_name TEXT, agency_url TEXT, agency_timezone TEXT, agency_lang TEXT, agency_phone TEXT, agency_fare_url TEXT);

CREATE TABLE routes (route_id TEXT, agency_id TEXT, route_short_name TEXT, route_long_name TEXT, route_desc TEXT, route_type TEXT, route_url TEXT, route_color TEXT, route_text_color TEXT);

CREATE TABLE trips (route_id TEXT, service_id TEXT, trip_id TEXT, trip_headsign TEXT, trip_short_name TEXT, direction_id TEXT, block_id TEXT, shape_id TEXT, wheelchair_accessible TEXT, bikes_allowed TEXT);

CREATE TABLE stops (stop_id TEXT, stop_code TEXT, stop_name TEXT, stop_desc TEXT, stop_lat TEXT, stop_lon TEXT, zone_id TEXT, stop_url TEXT, location_type TEXT, parent_station TEXT, stop_timezone TEXT, wheelchair_boarding TEXT);

CREATE TABLE stop_times (trip_id TEXT, arrival_time TEXT, departure_time TEXT, stop_id TEXT, stop_sequence TEXT, stop_headsign TEXT, pickup_type TEXT, drop_off_type TEXT, shape_dist_traveled TEXT, timepoint TEXT);

CREATE TABLE calendar (service_id TEXT, monday TEXT, tuesday TEXT, wednesday TEXT, thursday TEXT, friday TEXT, saturday TEXT, sunday TEXT, start_date TEXT, end_date TEXT);
